create type public.transaction_kind as enum ('entrada','saida');create type public.finance_category as enum ('projeto','servico','produto','prazo_labore','reembolso','distribuicao_lucros','imposto','equipe','ferramenta','infraestrutura','marketing','outro');
create table public.transacoes_financeiras(id uuid primary key default gen_random_uuid(),tipo public.transaction_kind not null,categoria public.finance_category not null default 'outro',descricao text not null,valor bigint not null check(valor>=0),projeto_id uuid references public.projetos(id) on delete set null,cliente_id uuid references public.clientes(id) on delete set null,vencimento timestamptz not null,pago boolean not null default false,pago_em timestamptz,metodo_pagamento text,criado_por uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_transacoes_vencimento on public.transacoes_financeiras(vencimento);create index idx_transacoes_pago on public.transacoes_financeiras(pago);create index idx_transacoes_projeto on public.transacoes_financeiras(projeto_id);
create trigger transacoes_updated_at before update on public.transacoes_financeiras for each row execute function public.tocar_updated_at();
create view public.vencimentos_em_aberto with(security_invoker=true) as select id,tipo,categoria,descricao,valor,vencimento,projeto_id,cliente_id,(vencimento<now()) as vencida from public.transacoes_financeiras where not pago order by vencimento asc;
alter table public.transacoes_financeiras enable row level security;
create policy transacoes_interno_crud on public.transacoes_financeiras for all to authenticated using(public.eh_interno()) with check(public.eh_interno());
revoke select on public.vencimentos_em_aberto from public,anon;grant select on public.vencimentos_em_aberto to authenticated;
